  --linear-space-36: 36px;
  --linear-space-40: 40px;
  --linear-space-48: 48px;
  --linear-space-56: 56px;
  --linear-space-64: 64px;
  --linear-space-80: 80px;
  --linear-space-96: 96px;
  --linear-space-128: 128px;
  --linear-radius-small: 2px;
  --linear-radius-badges: 4px;
  --linear-radius-inputs: 6px;
  --linear-radius-buttons: 6px;
  --linear-radius-cards: 12px;
  --linear-radius-pills: 9999px;
  --linear-shadow-sm: rgba(0, 0, 0, 0.4) 0 2px 4px;
  --linear-shadow-md: rgba(0, 0, 0, 0.2) 0 0 12px inset;
  --linear-shadow-subtle: rgb(35, 37, 42) 0 0 0 1px inset;
  --linear-shadow-subtle-2: rgba(0, 0, 0, 0.2) 0 0 0 1px;
  --linear-shadow-xl: rgba(8, 9, 10, 0.6) 0 4px 32px;
  --linear-shadow-subtle-5: rgba(0, 0, 0, 0.1) 0 0 0 2px;
  --linear-font: Inter Variable, Inter, sans-serif;
  --linear-mono: Berkeley Mono, JetBrains Mono, monospace;
}

/* Doodle Pop — lime × black sticker energy: thick ink borders, hard offset shadows,
 * polka-dot textures, coral/lavender/sky pastel pops. Original Vetta preset. */
@theme {
	--color-primary: #d6f437;
	--color-primary-foreground: #111111;
	--color-surface: #c8e93c;
	--color-surface-foreground: #111111;
	--color-surface-raised: #ffffff;
	--color-muted: #55584a;
	--color-accent: #f4794f;
	--color-danger: #ef3b5d;
	--color-border: #111111;
	--color-cream: #f2f0e6;
	--color-lavender: #b39df3;
	--color-sky: #8ed8e8;
	--color-ink: #111111;

	--radius-sm: 8px;
	--radius-md: 12px;
	--radius-lg: 16px;
	--radius-xl: 20px;
	--radius-2xl: 28px;

	--shadow-sm: 2px 2px 0 #111111;
	--shadow-md: 4px 4px 0 #111111;
	--shadow-lg: 7px 7px 0 #111111;
}

/* templates — light design system, converted from brands-design-md. */
@theme {
