  --font-primary: 'Airbnb Cereal VF', Circular, -apple-system, system-ui, Roboto, 'Helvetica Neue', sans-serif;
  --font-family-2: 'Airbnb Cereal VF', Circular, sans-serif;
  --text-display-xl: 28px;
  --leading-display-xl: 1.43;
  --tracking-display-xl: 0;
  --text-display-lg: 22px;
